static __device__ __forceinline__ void step_TopAccum_A(ExecContext& ctx,MutableBuf accum0, MutableBuf data1, GlobalBuf global2, GlobalBuf mix3)   {
// zirgen/dsl/passes/GenerateAccum.cpp:525
